import{_ as e,o as a,c as r,a2 as i}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Special Attacks and prepared actions","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/combat/special-attacks.md","filePath":"en/guide/combat/special-attacks.md"}'),d={name:"en/guide/combat/special-attacks.md"};function n(o,t,s,l,c,h){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="special-attacks-and-prepared-actions" tabindex="-1">Special Attacks and prepared actions <a class="header-anchor" href="#special-attacks-and-prepared-actions" aria-label="Permalink to &quot;Special Attacks and prepared actions&quot;">​</a></h1><p><strong>Status:</strong> Proposed framework · Experimental five-slot kit · Not implemented.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Special Attacks are learned techniques, then selected for a prepared kit.</li><li>The Experimental kit has 5 slots; basics use none and INT does not scale it yet.</li><li>Offense queues in Legacy and triggers in Modern; defense is manual and availability-gated in both.</li></ul><p>Special Attacks are learned techniques, not automatic rewards for reaching a skill number. Prepare a small kit and choose the right action for the opening.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Test direction</th></tr></thead><tbody><tr><td>Learning</td><td>Teachers, manuals, schools, exploration and challenges</td></tr><tr><td>Knowledge</td><td>Learned techniques remain known</td></tr><tr><td>Prepared kit</td><td>5 SA slots; basics use none; no INT scaling yet</td></tr><tr><td>Offensive actions</td><td>Legacy queues; Modern triggers</td></tr><tr><td>Defense</td><td>Manual in both modes, only when action phases permit</td></tr><tr><td>Familiarity</td><td>Learned → Practiced → Mastered improves execution modestly</td></tr></tbody></table><h2 id="first-weapon-kits" tabindex="-1">First weapon kits <a class="header-anchor" href="#first-weapon-kits" aria-label="Permalink to &quot;First weapon kits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Weapon</th><th>Basic</th><th>Three learned options</th></tr></thead><tbody><tr><td>Longsword</td><td>Basic Slash</td><td>Thrust, Feint, Riposte</td></tr><tr><td>Spear</td><td>Basic Thrust</td><td>Lunge, Brace, Sweep</td></tr><tr><td>War Hammer</td><td>Basic Swing</td><td>Heavy Blow, Crushing Arc, Guard Break</td></tr></tbody></table><h2 id="trade-offs" tabindex="-1">Trade-offs <a class="header-anchor" href="#trade-offs" aria-label="Permalink to &quot;Trade-offs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Choice</th><th>Purpose</th><th>Risk</th></tr></thead><tbody><tr><td>Feint</td><td>Invite an early defensive response</td><td>Costs stamina; deals no direct damage</td></tr><tr><td>Brace / Riposte</td><td>Answer a compatible attack</td><td>Wrong timing, flank or mismatch wastes commitment</td></tr><tr><td>Guard Break</td><td>Weaken an active stance for this hit</td><td>No permanent armor break or generic stun</td></tr><tr><td>Arc</td><td>Pressure up to two nearby hostiles</td><td>Lower precision and costly recovery</td></tr></tbody></table><h2 id="preparation" tabindex="-1">Preparation <a class="header-anchor" href="#preparation" aria-label="Permalink to &quot;Preparation&quot;">​</a></h2><ul><li>A technique must be known, prepared and compatible with the weapon.</li><li>Test swaps require no target, action or queue and 10 seconds without hostile action dealt/received.</li><li>Swapping never cancels recovery. Future INT effects remain unresolved.</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A prepared Brace can answer a committed Heavy Blow. A Feint may bait it without ever delivering that blow.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/combat/numeric-prototype.html">Action costs</a> · <a href="/Syrolands-Public/en/guide/characters/familiarity.html">Familiarity</a> · <a href="/Syrolands-Public/en/game-design/combat/actions.html">Full design</a></p>',17)])])}const m=e(d,[["render",n]]);export{u as __pageData,m as default};
